# Spearman's p by the t approximation, the reference for Level 1 (Phase 2
# evaluation fixes, part A, section 4). Run: /usr/local/bin/Rscript make_l1_spearman_fixtures.R
# p_t_approx is cor.test(x, y, method = "spearman", exact = FALSE)$p.value,
# what SPSS reports; p_exact is R's exact p (no ties only), which Level 1 does
# not compute.
set.seed(20261015)
cases <- list(
  no_ties_report_a01 = list(x = 1:12, y = c(30, 28, 29, 25, 26, 22, 24, 20, 21, 18, 19, 15)),
  no_ties_n15 = { x <- sample(1:15); list(x = x, y = round(x + rnorm(15, 0, 4), 2)) },
  ties_n20 = list(x = sample(1:6, 20, replace = TRUE), y = sample(1:5, 20, replace = TRUE) + sample(0:1, 20, replace = TRUE)),
  ties_n8 = list(x = c(1, 2, 2, 3, 4, 4, 5, 6), y = c(2, 1, 3, 3, 5, 4, 6, 6))
)
out <- file("spearman_tapprox.csv", "w")
writeLines(c(
  "# R reference for Spearman's t-approximation p (Phase 2 evaluation fixes, part A).",
  "# Generated by /usr/local/bin/Rscript make_l1_spearman_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string),
  "# x and y are ;-separated. Numbers are %.17g.",
  "case,x,y,ties,rho,df,p_t_approx,p_exact"), out)
for (nm in names(cases)) {
  x <- cases[[nm]]$x; y <- cases[[nm]]$y
  ties <- any(duplicated(x)) || any(duplicated(y))
  a <- suppressWarnings(cor.test(x, y, method = "spearman", exact = FALSE))
  e <- if (ties) NA else cor.test(x, y, method = "spearman", exact = TRUE)$p.value
  writeLines(paste(nm, paste(x, collapse = ";"), paste(y, collapse = ";"), ties,
    sprintf("%.17g", a$estimate), length(x) - 2, sprintf("%.17g", a$p.value),
    if (is.na(e)) "NA" else sprintf("%.17g", e), sep = ","), out)
}
close(out)
